<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';import {useRouter,useRoute} from 'vue-router';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';
import GovernanceListFrame from './GovernanceListFrame.vue';import GovernanceDrawer from './GovernanceDrawer.vue';import GovernanceResourcePicker from './GovernanceResourcePicker.vue';import QualityRulesEditor from './QualityRulesEditor.vue';import {useGovernanceList} from './useGovernanceList';
import {defaultRules,localTime,stateLabels,type Candidate,type CandidateDetail,type CandidatePage,type Catalog,type Rules} from './workbench-types';import type {Configuration,ModelConfiguration} from './operations-types';
const app=useApplication(),ops=app.operationsCommands,router=useRouter(),route=useRoute(),list=useGovernanceList<CandidatePage>('candidates');
const catalog=ref<Catalog|null>(null),current=ref<Configuration|null>(null),detail=ref<CandidateDetail|null>(null),drawer=ref<'create'|'detail'|'evaluate'|'publish'|'rollback'|null>(null),busy=ref(false),error=ref(''),notice=ref('');let epoch=0,resourceEpoch=0;
const title=ref(''),model=ref('harness-fixture-embedding-v1'),prompt=ref('summary-v1'),threshold=ref(''),rules=ref<Rules>(defaultRules()),reason=ref(''),dataset=ref(''),editing=ref<CandidateDetail|null>(null),rollbackRevision=ref('');
const locked=computed(()=>busy.value||ops.pending.value||!ops.available.value),config=computed<ModelConfiguration>(()=>({modelVersion:model.value,promptVersion:prompt.value,voiceThreshold:threshold.value===''?null:Number(threshold.value)}));
type HistoryPage=import('../../shared/api/generated').components['schemas']['OperationsConfigurationHistoryPage'];
const history=ref<HistoryPage['items']>([]),historyCursor=ref<string|null>(null),historyTotal=ref(0),historyBusy=ref(false),candidateHistoryCursor=ref<string|null>(null),candidateHistoryTotal=ref(0);let historyEpoch=0;
async function loadHistory(more=false){const turn=++historyEpoch;historyBusy.value=true;try{const p=await ops.read<HistoryPage>('/api/v1/operations/configuration/history?limit=20'+(more&&historyCursor.value?'&cursor='+encodeURIComponent(historyCursor.value):''));if(turn===historyEpoch){history.value=more?[...history.value,...p.items]:p.items;historyCursor.value=p.nextCursor;historyTotal.value=p.total;}}catch(cause){if(turn===historyEpoch)fail(cause);}finally{if(turn===historyEpoch)historyBusy.value=false;}}
async function moreCandidateHistory(){const d=detail.value;if(!d||!candidateHistoryCursor.value)return;const turn=epoch;try{const p=await ops.read<import('../../shared/api/generated').components['schemas']['OperationsCandidateHistoryPage']>(`/api/v1/operations/candidates/${d.id}/history?limit=20&cursor=${encodeURIComponent(candidateHistoryCursor.value)}`);if(turn===epoch&&detail.value?.id===d.id){detail.value={...d,history:[...d.history,...p.items]};candidateHistoryCursor.value=p.nextCursor;}}catch(cause){if(turn===epoch)fail(cause);}}
const selectedPrompt=computed(()=>catalog.value?.prompts.find(p=>p.id===prompt.value));
function fail(cause:unknown){error.value=cause instanceof Error?cause.message:'配置操作尚未确认。';}
async function resources(){const turn=++resourceEpoch;try{const [c,active]=await Promise.all([ops.read<Catalog>('/api/v1/operations/catalog'),ops.read<Configuration>('/api/v1/operations/configuration')]);if(turn===resourceEpoch){catalog.value=c;current.value=active;void loadHistory();}}catch(cause){if(turn===resourceEpoch)fail(cause);}}
function fill(c?:CandidateDetail){editing.value=c??null;title.value=c?.title??'';model.value=c?.configuration.modelVersion??catalog.value?.models[0]?.id??'harness-fixture-embedding-v1';prompt.value=c?.configuration.promptVersion??'summary-v1';threshold.value=c?.configuration.voiceThreshold?.toString()??'';rules.value=c?{...c.rules}:defaultRules();reason.value='';error.value='';drawer.value='create';}
async function open(id:string){const turn=++epoch;drawer.value='detail';detail.value=null;reason.value='';error.value='';try{const [data,h]=await Promise.all([ops.read<CandidateDetail>('/api/v1/operations/candidates/'+id),ops.read<import('../../shared/api/generated').components['schemas']['OperationsCandidateHistoryPage']>(`/api/v1/operations/candidates/${id}/history?limit=20`)]);if(turn===epoch){detail.value={...data,history:h.items};candidateHistoryCursor.value=h.nextCursor;candidateHistoryTotal.value=h.total;await router.replace({query:{...route.query,selected:id}});}}catch(cause){if(turn===epoch)fail(cause);}}
function close(){if(busy.value)return;epoch++;drawer.value=null;editing.value=null;reason.value='';error.value='';void router.replace({query:{...route.query,selected:undefined}});}
async function action(operation:()=>Promise<unknown>,message:string,after?:(value:unknown)=>void){if(locked.value)return;busy.value=true;error.value='';try{const result=await operation();notice.value=message;drawer.value=null;reason.value='';await Promise.all([list.load(),resources()]);after?.(result);}catch(cause){fail(cause);}finally{busy.value=false;}}
function save(){return action(()=>{if(!title.value.trim()||!reason.value.trim())throw Error('请填写配置名称和修改说明。');return ops.submit(editing.value?`/api/v1/operations/candidates/${editing.value.id}/edits`:'/api/v1/operations/candidates',{...(editing.value?{expectedRevisionToken:editing.value.revisionToken}:{}),title:title.value.trim(),configuration:config.value,rules:rules.value,reason:reason.value});},editing.value?'配置已更新，旧评测与审批资格已失效。':'候选配置已创建，请选择数据集运行评测。');}
function evaluate(){const d=detail.value;if(!d)return;return action(()=>ops.submit(`/api/v1/operations/candidates/${d.id}/evaluations`,{expectedRevisionToken:d.revisionToken,datasetId:dataset.value}),'评测已排队，规则与配置已冻结。',value=>void router.push('/operations/evaluation/'+(value as {id:string}).id));}
function publish(){const d=detail.value,c=current.value;if(!d||!c)return;return action(()=>ops.submit(`/api/v1/operations/candidates/${d.id}/publication`,{expectedRevisionToken:d.revisionToken,currentConfigurationRevisionToken:c.revisionToken,reason:reason.value}),'配置已发布。新任务采用新修订，在途任务保留原快照。');}
function rollback(){return action(()=>ops.submit('/api/v1/operations/rollback-candidates',{targetRevisionToken:rollbackRevision.value,title:title.value,reason:reason.value,rules:rules.value}),'回滚候选已创建，完成评测和独立审批后可发布。');}
function rollbackForm(){drawer.value='rollback';rollbackRevision.value='';title.value='';reason.value='';rules.value=defaultRules();error.value='';}
void resources();watch(()=>route.query.selected,id=>{if(typeof id==='string'&&detail.value?.id!==id)void open(id);else if(typeof id!=='string'&&drawer.value==='detail'){epoch++;drawer.value=null;detail.value=null;}},{immediate:true});watch(()=>ops.pending.value,(pending,was)=>{if(was&&!pending&&!busy.value){void resources();if(detail.value)void open(detail.value.id);}});onUnmounted(()=>{epoch++;resourceEpoch++;historyEpoch++;});
</script>
<template><p v-if="notice" class="gov-success" role="status">{{notice}}</p><p v-if="error&&!drawer" class="gov-error" role="alert">{{error}}<button class="btn sm" @click="resources">重新读取配置</button></p><section v-if="current" class="active-configuration"><div class="active-icon"><Icon name="shield" :size="24"/></div><div class="active-heading"><div><span class="gov-tag" data-state="EFFECTIVE">当前生效</span><strong>配置修订 {{current.revisionToken}}</strong></div><p>新任务使用当前配置，已开始的任务继续使用其冻结版本。</p></div><dl><div><dt>语音模型</dt><dd>{{current.configuration.modelVersion}}</dd></div><div><dt>纪要提示词</dt><dd>{{current.configuration.promptVersion}}</dd></div><div><dt>声纹阈值</dt><dd>{{current.configuration.voiceThreshold??'匹配关闭'}}</dd></div></dl><button class="btn sm" :disabled="locked" @click="rollbackForm"><Icon name="undo"/>回滚申请</button></section>
<GovernanceListFrame title="候选配置" description="先评测，再由另一名管理员复核，最后发布到新任务。" :counts="list.page.value?.counts??{}" :total="list.page.value?.total??null" :loading="list.loading.value" :error="list.error.value" v-model:query="list.query.value" :state="list.state()" :states="['DRAFT','APPROVED','PUBLISHED']" :next-cursor="list.page.value?.nextCursor" :has-cursor="list.hasCursor()" @search="list.search" @filter="list.filter('state',$event)" @refresh="list.load" @next="list.next" @first="list.first"><template #actions><button class="btn primary" :disabled="locked||!catalog" @click="fill()"><Icon name="plus"/>新建候选配置</button></template><div class="gov-table-wrap"><table class="gov-table"><thead><tr><th>配置名称</th><th>状态</th><th>内容指纹</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in list.page.value?.items" :key="item.id"><td class="primary-cell"><button class="gov-link" @click="open(item.id)">{{item.title}}</button><span class="sub-cell">候选修订 {{item.revisionToken}}</span></td><td><span class="gov-tag" :data-state="item.state">{{stateLabels[item.state]}}</span></td><td class="gov-muted">{{item.contentSha.slice(0,12)}}…</td><td>{{localTime(item.createdAt)}}</td><td><button class="gov-link" @click="open(item.id)">查看配置</button></td></tr></tbody></table></div><div v-if="!list.page.value?.items.length" class="gov-empty"><Icon name="shield" :size="32"/><h3>还没有候选配置</h3><p>从已安装的模型和提示词开始，建立可核对的评测与审批记录。</p></div></GovernanceListFrame>
<details v-if="history.length" class="configuration-history"><summary>发布历史 · 已载入 {{history.length}} / {{historyTotal}} 个修订</summary><table class="gov-table"><thead><tr><th>修订</th><th>发布说明</th><th>生效时间</th><th>证据</th></tr></thead><tbody><tr v-for="h in history" :key="h.revisionToken"><td>{{h.revisionToken}}</td><td>{{h.reason}}</td><td>{{localTime(h.createdAt)}}</td><td><RouterLink v-if="h.evaluationId" :to="'/operations/evaluation/'+h.evaluationId" class="gov-link">评测报告</RouterLink><span v-else class="gov-muted">安装初始配置</span></td></tr></tbody></table><button v-if="historyCursor" class="btn sm" :disabled="historyBusy" @click="loadHistory(true)">加载更早的修订</button></details>
<GovernanceDrawer v-if="drawer" :title="({create:editing?'编辑候选配置':'新建候选配置',detail:'配置详情',evaluate:'运行候选评测',publish:'发布配置',rollback:'创建回滚候选'})[drawer]" :subtitle="detail&&drawer!=='create'&&drawer!=='rollback'?detail.title:undefined" :wide="drawer==='create'||drawer==='rollback'" :busy="busy" @close="close"><p v-if="error" class="gov-error" role="alert">{{error}}</p><template v-if="drawer==='create'"><div class="gov-fields"><label>配置名称<input v-model="title" maxlength="160" :disabled="locked" placeholder="例如 11 月会议质量优化"/></label><label>已安装的语音模型<select v-model="model" :disabled="locked"><option v-for="item in catalog?.models" :key="item.id" :value="item.id">{{item.name}}</option></select><small>{{model}} · 仅支持当前安装目录中的身份</small></label><label>纪要提示词<select v-model="prompt" :disabled="locked"><option v-for="item in catalog?.prompts" :key="item.id" :value="item.id">{{item.name}} · {{item.id}}</option></select></label><p class="gov-note">{{selectedPrompt?.content}}</p><label>声纹候选阈值<input v-model="threshold" type="number" min="0.01" max="1" step="0.01" placeholder="留空则关闭候选匹配" :disabled="locked"/><small>启用匹配必须有同人和异人两类评测，分别满足 FRR 与 FAR 规则。</small></label></div><h3 class="gov-section-title">发布判定规则</h3><QualityRulesEditor v-model="rules" :disabled="locked"/><h3 class="gov-section-title">修改说明</h3><div class="gov-fields"><label>本次修改的目的<textarea v-model="reason" maxlength="2048" :disabled="locked"/></label></div></template>
<template v-else-if="drawer==='rollback'"><div class="gov-note">回滚会生成新的候选配置和发布修订。历史记录保留，仍需评测和另一名管理员复核。</div><div class="gov-fields"><label>目标历史修订<select v-model="rollbackRevision" :disabled="locked"><option value="">请选择修订</option><option v-for="h in history" :key="h.revisionToken" :value="h.revisionToken">修订 {{h.revisionToken}} · {{h.reason}}</option></select><button v-if="historyCursor" class="btn sm" :disabled="historyBusy" @click="loadHistory(true)">加载更早的修订</button></label><label>回滚候选名称<input v-model="title" maxlength="160" :disabled="locked"/></label><label>回滚原因<textarea v-model="reason" maxlength="2048" :disabled="locked"/></label></div><h3 class="gov-section-title">冻结判定规则</h3><QualityRulesEditor v-model="rules" :disabled="locked"/></template>
<template v-else-if="detail"><dl class="gov-definition"><dt>候选状态</dt><dd><span class="gov-tag" :data-state="detail.state">{{stateLabels[detail.state]}}</span></dd><dt>语音模型</dt><dd>{{detail.configuration.modelVersion}}</dd><dt>提示词</dt><dd>{{detail.configuration.promptVersion}}</dd><dt>匹配阈值</dt><dd>{{detail.configuration.voiceThreshold??'匹配关闭'}}</dd><dt>候选修订</dt><dd>{{detail.revisionToken}}</dd><dt>内容指纹</dt><dd>{{detail.contentSha}}</dd><dt v-if="detail.approvedBy">复核人</dt><dd v-if="detail.approvedBy">{{detail.approvedBy}}</dd><dt v-if="detail.approvalReason">复核意见</dt><dd v-if="detail.approvalReason">{{detail.approvalReason}}</dd></dl><section v-if="drawer==='detail'"><h3 class="gov-section-title">与当前配置比较</h3><dl class="gov-definition"><dt>语音模型</dt><dd>{{current?.configuration.modelVersion}} → {{detail.configuration.modelVersion}}</dd><dt>提示词</dt><dd>{{current?.configuration.promptVersion}} → {{detail.configuration.promptVersion}}</dd><dt>阈值</dt><dd>{{current?.configuration.voiceThreshold??'关闭'}} → {{detail.configuration.voiceThreshold??'关闭'}}</dd></dl><details><summary class="gov-section-title">冻结规则</summary><QualityRulesEditor :model-value="detail.rules" disabled/></details><h3 class="gov-section-title">变更历史 · {{detail.history.length}} / {{candidateHistoryTotal}}</h3><ol class="gov-history"><li v-for="h in detail.history" :key="h.revisionToken">{{localTime(h.createdAt)}} · 修订 {{h.revisionToken}}<p>{{h.reason}}</p></li></ol><button v-if="candidateHistoryCursor" class="btn sm" @click="moreCandidateHistory">加载更早的变更</button></section><section v-else-if="drawer==='evaluate'"><h3 class="gov-section-title">选择不可变数据集</h3><GovernanceResourcePicker module="datasets" v-model="dataset" label="评测数据集" :disabled="locked"/><p class="gov-note">开始后按样本显示进度。模型异常会保留失败记录，可取消或重试。</p></section><section v-else-if="drawer==='publish'"><h3 class="gov-section-title">发布说明</h3><p class="gov-note">本次将基于当前修订 {{current?.revisionToken}} 创建新修订。发布前会重新核验评测、审批人权限与候选版本。</p><div class="gov-fields"><label>发布原因<textarea v-model="reason" maxlength="2048" :disabled="locked"/></label></div></section></template><p v-else class="gov-muted">正在读取配置…</p>
<template #footer><button class="btn" :disabled="busy" @click="close">关闭</button><template v-if="drawer==='detail'&&detail"><button v-if="detail.state==='DRAFT'||detail.state==='APPROVED'" class="btn" :disabled="locked" @click="fill(detail)">编辑</button><button v-if="detail.state==='DRAFT'" class="btn primary" :disabled="locked" @click="drawer='evaluate';dataset='';reason=''">运行评测</button><button v-if="detail.state==='APPROVED'" class="btn primary" :disabled="locked" @click="drawer='publish';reason=''">发布配置</button><RouterLink v-if="detail.state==='PUBLISHED'&&detail.evaluationId" class="btn" :to="'/operations/evaluation/'+detail.evaluationId">评测证据</RouterLink></template><button v-else-if="drawer==='create'" class="btn primary" :disabled="locked||!title.trim()||!reason.trim()" @click="save">保存候选配置</button><button v-else-if="drawer==='evaluate'" class="btn primary" :disabled="locked||!dataset" @click="evaluate">开始评测</button><button v-else-if="drawer==='publish'" class="btn primary" :disabled="locked||!reason.trim()" @click="publish">确认发布</button><button v-else-if="drawer==='rollback'" class="btn primary" :disabled="locked||!rollbackRevision||!title.trim()||!reason.trim()" @click="rollback">创建回滚候选</button></template></GovernanceDrawer></template>
<style scoped>.active-configuration{background:#fff;border:1px solid #e3e5ee;border-radius:12px;margin-bottom:30px;padding:22px;display:flex;align-items:center;gap:20px;flex-wrap:wrap}.active-icon{width:48px;height:48px;border-radius:12px;background:#f1f2fa;display:grid;place-items:center}.active-heading{margin-right:auto}.active-heading>div{display:flex;gap:10px;align-items:center}.active-heading strong{font-size:14px}.active-heading p{font-size:11px;color:#969aa8;margin:8px 0 0}.active-configuration dl{display:flex;gap:22px;margin:0}.active-configuration dt{font-size:10px;color:#9b9eaa}.active-configuration dd{font-size:11px;margin:6px 0 0}.configuration-history{margin-top:24px;background:white;border:1px solid #e8e8ef;border-radius:10px;padding:18px}.configuration-history>summary{font-size:13px;font-weight:600;cursor:pointer}.configuration-history table{margin-top:14px}@media(max-width:1100px){.active-configuration dl{width:100%;order:3}.active-heading{flex:1}}</style>
